388	                    currentVersion = FileActivity.this.getPackageManager().getPackageInfo(FileActivity.this.getPackageName(), 0).versionName;
389	                    if (result != null && !result.isEmpty()) {
390	                        Log.d(TAG, "Current version: '" + currentVersion + "' PlayStore version: '" + result + "'");
391	                        Integer currentVersionInt = Integer.valueOf(currentVersion.replaceAll("\\.", ""));
392	                        Integer onlineVersionInt = Integer.valueOf(result.replaceAll("\\.", ""));
393	                        if (currentVersionInt < onlineVersionInt) {
394	                            Intent intent = new Intent(Intent.ACTION_VIEW, Uri.parse("market://details?id=io.lerk.lrkfm"));
395	                            intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
396	                            PendingIntent pendingIntent = PendingIntent.getActivity(FileActivity.this.getApplicationContext(), 0, intent, 0);
397	                            NotificationCompat.Builder notificationBuilder = new NotificationCompat.Builder(FileActivity.this, CHANNEL_ID)
398	                                    .setSmallIcon(R.drawable.ic_launcher)
399	                                    .setContentTitle(FileActivity.this.getText(R.string.notif_update_title))
400	                                    .setContentText(FileActivity.this.getText(R.string.notif_update_content) + result)
401	                                    .setPriority(NotificationCompat.PRIORITY_DEFAULT)
402	                                    .setContentIntent(pendingIntent)
403	                                    .setAutoCancel(true);
404	                            NotificationManagerCompat.from(FileActivity.this.getApplicationContext()).notify(NEW_VERSION_NOTIF, notificationBuilder.build());
405	                        }
406	                    }
407	                } catch (PackageManager.NameNotFoundException e) {
408	                    Log.e(TAG, "Unable to get package name!", e);
409	                }
410	            }).execute();
411	        }
412	    }
