450	    private void loadUserBookmarks() {
451	        Menu menu = navigationView.getMenu();
452	        TreeSet<String> bookmarks;
453	        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.N) {
454	            bookmarks = new TreeSet<>(Comparator.comparing(this::getTitleFromPath));
455	        } else { // FUCK THEM PUNY OLD VERSION USERS!
456	            //noinspection ComparatorCombinators
457	            bookmarks = new TreeSet<>((o1, o2) -> getTitleFromPath(o1).compareTo(getTitleFromPath(o2)));
458	        }
459	        bookmarks.addAll(new PrefUtils<HashSet<String>>(BOOKMARKS).getValue());
460	        if (!bookmarks.isEmpty()) {
461	            bookmarkItems = new HashSet<>();
462	            menu.removeGroup(R.id.bookmarksMenuGroup);
463	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
464	                bookmarks.forEach((s) -> addBookmarkToMenu(menu, s, bookmarks));
465	            } else { // also fuck all of those vendors that don't update. You are making development ugly!
466	                for (String s : bookmarks) {
467	                    addBookmarkToMenu(menu, s, bookmarks);
468	                }
469	            }
470	        } else {
471	            Log.d(TAG, "User has no bookmarks");
472	        }
473	    }
