482	    private void addBookmarkToMenu(Menu menu, String s, Set<String> bookmarks) {
483	        String title = getTitleFromPath(s);
484	        MenuItem item = menu.add(R.id.bookmarksMenuGroup, Menu.NONE, 2, title);
485	        item.setIcon(R.drawable.ic_bookmark_border_black_24dp);
486	        Bookmark bookmark = new Bookmark(s, title, item);
487	        if (new PrefUtils<Boolean>(BOOKMARK_EDIT_MODE).getValue()) {
488	            item.setActionView(R.layout.editable_menu_item);
489	            View v = item.getActionView();
490	            ImageButton deleteButton = v.findViewById(R.id.menu_item_action_delete);
491	            deleteButton.setOnClickListener(v0 -> removeBookmarkFromMenu(menu, s, bookmarks, item, bookmark));
492	            ImageButton editButton = v.findViewById(R.id.menu_item_action_edit);
493	            editButton.setOnClickListener((v1) -> {
494	                AlertDialog dia = new AlertDialog.Builder(this)
495	                        .setView(R.layout.layout_path_prompt)
496	                        .setNegativeButton(R.string.cancel, (dialog, which) -> Log.d(TAG, "Operation canceled."))
497	                        .create();
498	                dia.setOnShowListener(dialog -> ((EditText) dia.findViewById(R.id.destinationPath)).setText(s));
499	                dia.setButton(DialogInterface.BUTTON_POSITIVE, getString(R.string.okay), (dialog, which) -> {
500	                    removeBookmarkFromMenu(menu, s, bookmarks, item, bookmark);
501	                    addBookmarkToMenu(menu, ((EditText) dia.findViewById(R.id.destinationPath)).getText().toString(), bookmarks);
502	                });
503	                dia.show();
504	            });
505	        }
506	        bookmarkItems.add(bookmark);
507	    }
