509	    /**
510	     * Returns the last part of a path.
511	     *
512	     * @param s absolute path
513	     * @return last item of path
514	     */
515	    public String getTitleFromPath(String s) {
516	        if (s != null) {
517	            if (!s.equals(ROOT_DIR)) {
518	                String[] split = s.split("/");
519	                int i = split.length - 1;
520	                if (i < 0) {
521	                    i = 0;
522	                }
523	                return split[i];
524	            } else {
525	                return s;
526	            }
527	        } else {
528	            return "null";
529	        }
530	    }
