669	     * @param pref  chosen preference
670	     * @return sorted list
671	     */
672	    private ArrayList<FMFile> sortFilesByPreference(ArrayList<FMFile> files, String pref) {
673	        if (pref.equals(getString(R.string.pref_sortby_value_name))) {
674	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
675	                files.sort(Comparator.comparing(FMFile::getName));
676	            } else { // FUCKING OUT OF DATE USERS >.<
677	                //noinspection ComparatorCombinators,RedundantCast
678	                Arrays.sort((FMFile[]) files.toArray(new FMFile[files.size()]), (o1, o2) -> o1.getName().compareTo(o2.getName()));
679	            }
680	        } else if (pref.equals(getString(R.string.pref_sortby_value_date))) {
681	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.N) {
682	                files.sort(Comparator.comparing(FMFile::getLastModified));
683	            } else { // you see how beautiful the code above is?
684	                //noinspection ComparatorCombinators,RedundantCast
685	                Arrays.sort((FMFile[]) files.toArray(new FMFile[files.size()]), (o1, o2) -> o1.getLastModified().compareTo(o2.getLastModified()));
686	            }
