46	    @Override
47	    protected void openFile(FMFile f) {
48	        if (new PrefUtils<Boolean>(ZIPS_EXPLORABLE).getValue() && f.isArchive() && !(f instanceof FMArchive)) {
49	            activity.loadPath(f.getAbsolutePath());
50	        } else {
51	            Intent i = new Intent(Intent.ACTION_VIEW);
52	            String mimeType = f.getFileType().getMimeType();
53	            i.setDataAndType(Uri.fromFile(f.getFile()), mimeType);
54	            i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
55	            try {
56	                getContext().startActivity(i);
57	            } catch (ActivityNotFoundException e) {
58	                Toast.makeText(getContext(), R.string.no_app_to_handle_file, LENGTH_SHORT).show();
59	            }
60	        }
61	    }
