63	    /**
64	     * Gets the size of a file as formatted string.
65	     *
66	     * @param f the file
67	     * @return the size, formatted.
68	     */
69	    private String getSizeFormatted(FMFile f) {
70	        String[] units = new String[]{"B", "KiB", "MiB", "GiB", "TiB", "PiB"};
71	        Long length = f.getFile().length();
72	        if (Objects.equals(length, 0L)) {
73	            return "0";
74	        }
75	        Double number = Math.floor(Math.log(length) / Math.log(1024));
76	        Double pow = Math.pow(1024, Math.floor(number));
77	        Double d = length / pow;
78	        String formattedString = d.toString().substring(0, d.toString().indexOf(".") + 2);
79	        return formattedString + ' ' + units[number.intValue()];
80	    }
