90	        assert activity != null;
91	
92	        @SuppressLint("InflateParams") View v = LayoutInflater.from(activity).inflate(R.layout.layout_file, null); // works.
93	
94	        if (f != null) {
95	            TextView fileNameView = v.findViewById(R.id.fileTitle);
96	            TextView filePermissions = v.findViewById(R.id.filePermissions);
97	            TextView fileDate = v.findViewById(R.id.fileDate);
98	            TextView fileSize = v.findViewById(R.id.fileSize);
99	            ImageView fileImage = v.findViewById(R.id.fileIcon);
100	
101	            final String fileName = f.getName();
102	            if (fileNameView != null) {
103	                int maxLength = Integer.parseInt(new PrefUtils<String>(FILENAME_LENGTH).getValue());
104	                if (fileName.length() >= maxLength) {
105	                    @SuppressLint("SetTextI18n") String output = fileName.substring(0, maxLength - 3) + "...";
106	                    fileNameView.setText(output); //shorten long names
107	                } else {
108	                    fileNameView.setText(fileName);
109	                }
110	            }
111	            if (filePermissions != null) {
112	                filePermissions.setText(f.getPermissions());
113	            }
114	            if (fileDate != null) {
115	                fileDate.setText(SimpleDateFormat.getDateTimeInstance().format(f.getLastModified()));
116	            }
117	            if (fileSize != null) {
118	                if (f.isDirectory()) {
119	                    fileSize.setVisibility(View.GONE);
120	                } else {
121	                    fileSize.setText(getSizeFormatted(f));
122	                }
123	            }
124	            if (fileImage != null) {
125	                if (!f.isDirectory()) {
126	                    if (f.isArchive()) {
127	                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_perm_media_black_24dp));
128	                    } else {
129	                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_insert_drive_file_black_24dp));
130	                    }
131	                }
132	            }
133	            if (f.isDirectory() || (f.isArchive() && new PrefUtils<Boolean>(ZIPS_EXPLORABLE).getValue())) {
134	                v.setOnClickListener(v1 -> activity.loadPath(f.getFile().getAbsolutePath()));
135	            } else {
136	                v.setOnClickListener(v1 -> openFile(f));
137	            }
138	            v.setOnCreateContextMenuListener((menu, view, info) -> new ContextMenuUtil(activity, this).initializeContextMenu(f, fileName, menu));
139	            ImageButton contextButton = v.findViewById(R.id.contextMenuButton);
140	            contextButton.setOnClickListener(v1 -> activity.getFileListView().showContextMenuForChild(v));
141	
142	            for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
143	                if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
144	                    v.setBackgroundColor(activity.getColor(R.color.primary));
145	                }
146	            }
147	        }
148	        return v;
149	    }
