/**
 * The {@link android.widget.ArrayAdapter} implementation used in the {@link #fileListView}.
 */
private BaseArrayAdapter arrayAdapter;

/**
 * Index of the first visible item of the {@link #fileListView}.
 * Used to restore the scroll position when reloading the current directory.
 *
 * @see #saveScrollPosition()
 * @see #restoreScrollPosition()
 */
private int scrollPosition = 0;

/**
 * Offset (in pixels) of the first visible item of the {@link #fileListView}.
 * Used to restore the scroll position when reloading the current directory.
 *
 * @see #saveScrollPosition()
 * @see #restoreScrollPosition()
 */
private int scrollOffset = 0;

/**
 * F5
 */
public void reloadCurrentDirectory() {
    loadPath(currentDirectory);
}

/**
 * Saves the current scroll position of the {@link #fileListView}
 * so it can be restored after the list has been reloaded.
 *
 * @see #restoreScrollPosition()
 */
private void saveScrollPosition() {
    if (fileListView != null) {
        scrollPosition = fileListView.getFirstVisiblePosition();
        View firstVisibleItem = fileListView.getChildAt(0);
        scrollOffset = (firstVisibleItem == null) ? 0 : (firstVisibleItem.getTop() - fileListView.getPaddingTop());
    } else {
        resetScrollPosition();
    }
}

/**
 * Resets the saved scroll position, making the list start at the top.
 * This is used whenever an actual directory change happens.
 *
 * @see #saveScrollPosition()
 */
private void resetScrollPosition() {
    scrollPosition = 0;
    scrollOffset = 0;
}

/**
 * Restores the scroll position saved by {@link #saveScrollPosition()}.
 * Has to be called after the adapter has been set on the {@link #fileListView}.
 *
 * @see #saveScrollPosition()
 */
private void restoreScrollPosition() {
    if (fileListView != null && (scrollPosition > 0 || scrollOffset != 0)) {
        fileListView.setSelectionFromTop(scrollPosition, scrollOffset);
    }
}

